using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using Osynix.Ats.Data;
using Osynix.Ats.Domain;
namespace Osynix.Ats.Services;
public record WorkInvitation(Guid Id,string Employer,string Link,DateTime ExpiresUtc);
public record WorkPosition(Guid WorkspaceId,Guid Id,string Employer,string Client,string Reference,string Title,string Status,bool Personal);
public record WorkSubmission(Guid WorkspaceId,string Employer,string Client,string Position,string Reference,string Candidate,string Audience,string Status,string Remarks,DateTime SubmittedUtc,bool Pending,Guid AssessmentId=default);
public record WorkClient(string Name,string Industry);
public record RecruiterWorkOverview(Guid? PersonalWorkspace,int PersonalSlotsUsed,int PersonalSlotsLimit,int ActiveClients,List<WorkPosition> Positions,List<WorkspaceChoice> Teams,List<WorkInvitation> Invitations,List<WorkSubmission> Submissions,List<WorkClient> Clients);
public record WorkNotifications(List<WorkInvitation> Invitations,List<WorkPosition> Assignments);
public class RecruiterWorkService(AuthenticationStateProvider auth,IDbContextFactory<AtsDbContext> factory,IDataProtectionProvider protection){
 readonly IDataProtector tokens=protection.CreateProtector("Osynix.EmployerInvitation.v1");
 async Task<(AtsUser,ClaimsPrincipal)> Account(AtsDbContext db){var principal=(await auth.GetAuthenticationStateAsync()).User;var uid=principal.FindFirstValue(ClaimTypes.NameIdentifier);var account=await db.Users.FindAsync(uid);if(principal.Identity?.IsAuthenticated!=true||account is null||account.Status!="Active"||!account.EmailConfirmed)throw new UnauthorizedAccessException("An Active Verified Account Is Required.");var roles=await (from ur in db.UserRoles join role in db.Roles on ur.RoleId equals role.Id where ur.UserId==uid select role.Name!).ToListAsync();if(!roles.Order().SequenceEqual(principal.FindAll(ClaimTypes.Role).Select(c=>c.Value).Order())||!roles.Any(r=>r is "Recruiter" or "Employer" or "Admin"))throw new UnauthorizedAccessException("Your Account Access Changed. Sign In Again.");return(account,principal);}
 async Task<List<WorkInvitation>> Invites(AtsDbContext db,AtsUser account){var email=(account.Email??"").ToUpperInvariant();var raw=await (from i in db.EmployerInvitations.AsNoTracking() join w in db.EmployerWorkspaces on i.WorkspaceId equals w.Id where i.NormalizedEmail==email&&i.Status=="Pending"&&i.ExpiresUtc>DateTime.UtcNow orderby i.CreatedUtc descending select new{i,w.OwnerId,w.CompanyName,w.Kind}).ToListAsync();var result=new List<WorkInvitation>();foreach(var item in raw){if(item.Kind==AccountTypes.Freelance||!await WorkspaceContext.OwnerActive(db,item.OwnerId))continue;try{result.Add(new(item.i.Id,item.CompanyName,"/Account/TeamInvitation?token="+Uri.EscapeDataString(tokens.Unprotect(item.i.ProtectedToken)),item.i.ExpiresUtc));}catch(System.Security.Cryptography.CryptographicException){}}return result;}
 public async Task<RecruiterWorkOverview> Overview(){await using var db=await factory.CreateDbContextAsync();var(account,principal)=await Account(db);var choices=await WorkspaceContext.Choices(db,principal);var own=choices.FirstOrDefault(c=>c.Owner);var ownId=own?.Id;var teams=choices.Where(c=>!c.Owner).ToList();var ids=teams.Select(t=>t.Id).ToList();var rows=await db.Positions.AsNoTracking().Where(p=>(ownId!=null&&p.WorkspaceId==ownId)||(p.WorkspaceId!=null&&ids.Contains(p.WorkspaceId.Value)&&(p.AssignedRecruiter==account.UserName||db.PositionRecruiterAssignments.Any(pa=>pa.PositionId==p.Id&&db.Users.Any(au=>au.Id==pa.UserId&&au.UserName==account.UserName))))).OrderByDescending(p=>p.UpdatedUtc).ToListAsync();var positions=rows.Select(p=>new WorkPosition(p.WorkspaceId!.Value,p.Id,own?.Id==p.WorkspaceId?"Independent Client Work":teams.Single(t=>t.Id==p.WorkspaceId).Name,p.Client,p.Reference,p.Title,p.Status,p.WorkspaceId==own?.Id)).ToList();var allowed=rows.Select(p=>p.Id).ToList();var applications=await db.Assessments.AsNoTracking().Where(a=>a.State=="Saved"&&allowed.Contains(a.PositionId)).ToListAsync();var applicationIds=applications.Select(a=>a.Id).ToList();var clientSubmissions=await db.HiringSubmissions.AsNoTracking().Where(s=>s.SubmittedBy==account.Id&&!s.Revoked&&applicationIds.Contains(s.AssessmentId)).ToListAsync();var employerSubmissions=await db.EmployerProfileSubmissions.AsNoTracking().Where(s=>s.SubmittedBy==account.Id&&applicationIds.Contains(s.AssessmentId)).ToListAsync();var submissions=new List<WorkSubmission>();
 foreach(var s in clientSubmissions.GroupBy(s=>s.AssessmentId).Select(g=>g.OrderByDescending(s=>s.SubmittedUtc).First())){var a=applications.Single(a=>a.Id==s.AssessmentId);var p=positions.Single(p=>p.Id==a.PositionId);submissions.Add(new(p.WorkspaceId,p.Employer,p.Client,p.Title,p.Reference,a.CandidateName,"Client",s.Feedback,s.Remarks,s.SubmittedUtc,s.Feedback=="Awaiting Feedback",a.Id));}
 foreach(var s in employerSubmissions){var a=applications.Single(a=>a.Id==s.AssessmentId);var p=positions.Single(p=>p.Id==a.PositionId);submissions.Add(new(p.WorkspaceId,p.Employer,p.Client,p.Title,p.Reference,a.CandidateName,"Employer",s.Status,s.Remarks,s.SubmittedUtc,s.Status=="Awaiting Employer Review",a.Id));}
 var workspace=own is null?null:await db.EmployerWorkspaces.AsNoTracking().SingleAsync(w=>w.Id==own.Id);var clients=own is null?new List<WorkClient>():await db.Clients.AsNoTracking().Where(c=>c.WorkspaceId==own.Id&&c.Status=="Active").OrderBy(c=>c.Name).Select(c=>new WorkClient(c.Name,c.Industry)).ToListAsync();return new(own?.Id,positions.Count(p=>p.Personal&&p.Status is "Active" or "On Hold"),workspace is null?0:workspace.FreePositionSlots+workspace.AdditionalPositionSlots,clients.Count,positions,teams,await Invites(db,account),submissions.OrderByDescending(s=>s.SubmittedUtc).ToList(),clients);
 }
 public async Task<WorkNotifications> Notifications(){await using var db=await factory.CreateDbContextAsync();var(account,principal)=await Account(db);if(principal.IsInRole("Admin"))return new([],[]);var choices=await WorkspaceContext.Choices(db,principal);var teams=choices.Where(c=>!c.Owner).ToList();var ids=teams.Select(c=>c.Id).ToList();var assigned=await db.Positions.AsNoTracking().Where(p=>p.WorkspaceId!=null&&ids.Contains(p.WorkspaceId.Value)&&(p.AssignedRecruiter==account.UserName||db.PositionRecruiterAssignments.Any(pa=>pa.PositionId==p.Id&&db.Users.Any(au=>au.Id==pa.UserId&&au.UserName==account.UserName)))&&(p.Status=="Active"||p.Status=="On Hold")).OrderByDescending(p=>p.UpdatedUtc).Take(5).ToListAsync();return new(await Invites(db,account),assigned.Select(p=>new WorkPosition(p.WorkspaceId!.Value,p.Id,teams.Single(t=>t.Id==p.WorkspaceId).Name,p.Client,p.Reference,p.Title,p.Status,false)).ToList());}
}
